	@ParameterizedTest
	@ValueSource(longs = { 2L * 1024L * 1024L, 8L * 1024L * 1024L })
	void ownedSynopsisRebuildsAndPersistsAfterBudgetChange(long newBudget,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStore initial = new LmdbStore(directory.toFile(), config(false));
		try (AutoCloseable shutdown = initial::shutDown) {
			initial.init();
			try (NotifyingSailConnection connection = initial.getConnection()) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.addStatement(VF.createIRI("urn:late-synopsis:s"), P, O);
				connection.commit();
			}
		}
		LmdbLegacyV4TestFixture.install(directory);
		LmdbStore seed = new LmdbStore(directory.toFile(), config(true));
		try (AutoCloseable shutdown = seed::shutDown) {
			seed.init();
			LmdbTestUtil.awaitPostReadyInitialization(seed, 20, TimeUnit.SECONDS);
			assertTrue(seed.awaitSketchesReady(20, TimeUnit.SECONDS));
		}
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		Path snapshot = directory.resolve(".rdf4j-estimator-" + properties.getOrCreateStoreId())
				.resolve("synopsis/synopsis-v8.bin");
		byte[] original = Files.readAllBytes(snapshot);
		try (AutoCloseable preserve = () -> LmdbLegacyV4TestFixture.assertUnchanged(directory)) {
			LmdbStore changed = new LmdbStore(directory.toFile(), config(true, newBudget));
			try (AutoCloseable shutdown = changed::shutDown) {
				changed.init();
				LmdbTestUtil.awaitPostReadyInitialization(changed, 20, TimeUnit.SECONDS);
				assertTrue(changed.awaitSketchesReady(20, TimeUnit.SECONDS));
				SketchBasedJoinEstimator estimator = changed.getBackingStore().getSketchBasedJoinEstimator();
				assertTrue(rows(estimator).usable());
				assertEquals(1.0d, rows(estimator).rows().estimate(), 0.0d);
				assertTrue(estimator.persistIfDirty(), "a previously owned snapshot can be rebuilt for the new budget");
			}
			assertFalse(Arrays.equals(original, Files.readAllBytes(snapshot)),
					"the budget change produced a new snapshot");
			LmdbStore reopened = new LmdbStore(directory.toFile(), config(true, newBudget));
			try (AutoCloseable shutdown = reopened::shutDown) {
				reopened.init();
				LmdbTestUtil.awaitPostReadyInitialization(reopened, 20, TimeUnit.SECONDS);
				assertTrue(reopened.awaitSketchesReady(20, TimeUnit.SECONDS));
				assertEquals(1.0d, rows(reopened.getBackingStore().getSketchBasedJoinEstimator()).rows().estimate(),
						0.0d);
			}
		}
	}

	private static QuadEvidence rows(SketchBasedJoinEstimator estimator) {
		return estimator.synopsisService()
				.probe(new QuadProbe(QuadProbe.PREDICATE, QuadProbe.SUBJECT, 0L,
						QuadValueHash.hash(P), 0L, 0L, estimator.quadSnapshotIdentity()));
	}

	private static LmdbStoreConfig config(boolean sketches) {
		return config(sketches, 4L * 1024L * 1024L);
	}

	private static LmdbStoreConfig config(boolean sketches, long budget) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setSketchEstimatorEnabled(sketches)
				.setBackgroundRawSamplingEnabled(false)
				.setSketchEstimatorMemoryBudgetBytes(budget);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
